{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE SNITCH_DB.MAPLEMONK.RPT_PARETO_HIERARCHY_GAP_MATRIX_META AS WITH STORE_PERF AS ( SELECT REPORT_MONTH, MONTH_LABEL, LOCATION_ID AS BRANCH_CODE, LOCATION_NAME AS STORE_NAME, CATEGORY, STYLE, META1, META2, META3, PRICE_SLAB_CODE, PRICE_RANGE_LABEL, SALES_UNITS, PARETO_ABCD_RANK FROM SNITCH_DB.MAPLEMONK.FACT_PARETO_SLAB_PERFORMANCE_META WHERE HIERARCHY_LEVEL = \'3. Store Wise\' ), CLUSTER_PERF AS ( SELECT REPORT_MONTH, LOCATION_ID AS CLUSTER_NAME, CATEGORY, STYLE, META1, META2, META3, PRICE_SLAB_CODE, PARETO_ABCD_RANK FROM SNITCH_DB.MAPLEMONK.FACT_PARETO_SLAB_PERFORMANCE_META WHERE HIERARCHY_LEVEL = \'2. Cluster Wise\' ), COMPANY_PERF AS ( SELECT REPORT_MONTH, CATEGORY, STYLE, META1, META2, META3, PRICE_SLAB_CODE, PARETO_ABCD_RANK FROM SNITCH_DB.MAPLEMONK.FACT_PARETO_SLAB_PERFORMANCE_META WHERE HIERARCHY_LEVEL = \'1. Company Wide\' ) SELECT S.REPORT_MONTH, S.MONTH_LABEL, S.BRANCH_CODE, S.STORE_NAME, M.ZONE, COALESCE(M.CLUSTER_NAME, \'UNMAPPED_CLUSTER\') AS CLUSTER_NAME, S.CATEGORY, S.STYLE, S.META1, S.META2, S.META3, S.PRICE_SLAB_CODE, S.PRICE_RANGE_LABEL, S.SALES_UNITS AS STORE_SALES_UNITS, S.PARETO_ABCD_RANK AS STORE_PARETO_RANK, COALESCE(CL.PARETO_ABCD_RANK, \'D\') AS CLUSTER_PARETO_RANK, COALESCE(CP.PARETO_ABCD_RANK, \'D\') AS COMPANY_PARETO_RANK, CASE WHEN S.PARETO_ABCD_RANK <> CP.PARETO_ABCD_RANK THEN TRUE ELSE FALSE END AS IS_MISMATCH, CASE WHEN S.PARETO_ABCD_RANK < CP.PARETO_ABCD_RANK THEN \'OVERPERFORMING\' WHEN S.PARETO_ABCD_RANK > CP.PARETO_ABCD_RANK THEN \'UNDERPERFORMING\' ELSE \'ALIGNED\' END AS MISMATCH_TYPE, CURRENT_TIMESTAMP() AS UPDATED_AT FROM STORE_PERF S LEFT JOIN SNITCH_DB.MAPLEMONK.STORE_ZONE_MAP M ON CAST(S.BRANCH_CODE AS VARCHAR) = CAST(M.BRANCH_CODE AS VARCHAR) LEFT JOIN CLUSTER_PERF CL ON S.REPORT_MONTH = CL.REPORT_MONTH AND M.CLUSTER_NAME = CL.CLUSTER_NAME AND EQUAL_NULL(S.CATEGORY, CL.CATEGORY) AND EQUAL_NULL(S.STYLE, CL.STYLE) AND EQUAL_NULL(S.META1, CL.META1) AND EQUAL_NULL(S.META2, CL.META2) AND EQUAL_NULL(S.META3, CL.META3) AND S.PRICE_SLAB_CODE = CL.PRICE_SLAB_CODE LEFT JOIN COMPANY_PERF CP ON S.REPORT_MONTH = CP.REPORT_MONTH AND EQUAL_NULL(S.CATEGORY, CP.CATEGORY) AND EQUAL_NULL(S.STYLE, CP.STYLE) AND EQUAL_NULL(S.META1, CP.META1) AND EQUAL_NULL(S.META2, CP.META2) AND EQUAL_NULL(S.META3, CP.META3) AND S.PRICE_SLAB_CODE = CP.PRICE_SLAB_CODE;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            